import { describe, expect, it, vi, beforeEach, afterEach } from "vitest";
import { getBotData, getConversationHistory } from "./api";

describe("api", () => {
  const originalFetch = global.fetch;

  beforeEach(() => {
    global.fetch = vi.fn();
  });

  afterEach(() => {
    global.fetch = originalFetch;
    vi.clearAllMocks();
  });

  describe("getBotData", () => {
    it("calls fetch with the correct URL when no authToken is provided", async () => {
      const mockResponse = {
        flows: {},
        assistant_id: "test-assistant",
      };

      vi.mocked(global.fetch).mockResolvedValueOnce({
        ok: true,
        json: () => Promise.resolve(mockResponse),
      } as Response);

      await getBotData({
        projectUrl: "http://localhost:5005",
        botDataEndpoint: "/data",
      });

      const fetchMock = vi.mocked(global.fetch);
      expect(fetchMock).toHaveBeenCalledTimes(1);
      const callArgs = fetchMock.mock.calls[0];
      expect(callArgs?.[0]).toBe("http://localhost:5005/data");
    });

    it("appends token query parameter when authToken is provided", async () => {
      const mockResponse = {
        flows: {},
        assistant_id: "test-assistant",
      };

      vi.mocked(global.fetch).mockResolvedValueOnce({
        ok: true,
        json: () => Promise.resolve(mockResponse),
      } as Response);

      await getBotData({
        projectUrl: "http://localhost:5005",
        botDataEndpoint: "/data",
        authToken: "test-token-123",
      });

      const fetchMock = vi.mocked(global.fetch);
      expect(fetchMock).toHaveBeenCalledTimes(1);
      const callArgs = fetchMock.mock.calls[0];
      expect(callArgs?.[0]).toBe("http://localhost:5005/data?token=test-token-123");
    });

    it("does not append token when authToken is undefined", async () => {
      const mockResponse = {
        flows: {},
        assistant_id: "test-assistant",
      };

      vi.mocked(global.fetch).mockResolvedValueOnce({
        ok: true,
        json: () => Promise.resolve(mockResponse),
      } as Response);

      await getBotData({
        projectUrl: "http://localhost:5005",
        botDataEndpoint: "/data",
        authToken: undefined,
      });

      const fetchMock = vi.mocked(global.fetch);
      expect(fetchMock).toHaveBeenCalledTimes(1);
      const callArgs = fetchMock.mock.calls[0];
      expect(callArgs?.[0]).toBe("http://localhost:5005/data");
    });
  });

  describe("getConversationHistory", () => {
    it("calls fetch with the correct URL when no authToken is provided", async () => {
      const mockResponse = {
        sender_id: "test-session",
        events: [],
        latest_message: null,
        slots: {},
        stack: [],
      };

      vi.mocked(global.fetch).mockResolvedValueOnce({
        ok: true,
        json: () => Promise.resolve(mockResponse),
      } as Response);

      await getConversationHistory({
        projectUrl: "http://localhost:5005",
        trackerEndpoint: "/conversations/test-session/tracker",
      });

      const fetchMock = vi.mocked(global.fetch);
      expect(fetchMock).toHaveBeenCalledTimes(1);
      const callArgs = fetchMock.mock.calls[0];
      expect(callArgs?.[0]).toBe("http://localhost:5005/conversations/test-session/tracker");
    });

    it("appends token query parameter when authToken is provided", async () => {
      const mockResponse = {
        sender_id: "test-session",
        events: [],
        latest_message: null,
        slots: {},
        stack: [],
      };

      vi.mocked(global.fetch).mockResolvedValueOnce({
        ok: true,
        json: () => Promise.resolve(mockResponse),
      } as Response);

      await getConversationHistory({
        projectUrl: "http://localhost:5005",
        trackerEndpoint: "/conversations/test-session/tracker",
        authToken: "my-secret-token",
      });

      const fetchMock = vi.mocked(global.fetch);
      expect(fetchMock).toHaveBeenCalledTimes(1);
      const callArgs = fetchMock.mock.calls[0];
      expect(callArgs?.[0]).toBe(
        "http://localhost:5005/conversations/test-session/tracker?token=my-secret-token",
      );
    });

    it("does not append token when authToken is undefined", async () => {
      const mockResponse = {
        sender_id: "test-session",
        events: [],
        latest_message: null,
        slots: {},
        stack: [],
      };

      vi.mocked(global.fetch).mockResolvedValueOnce({
        ok: true,
        json: () => Promise.resolve(mockResponse),
      } as Response);

      await getConversationHistory({
        projectUrl: "http://localhost:5005",
        trackerEndpoint: "/conversations/test-session/tracker",
        authToken: undefined,
      });

      const fetchMock = vi.mocked(global.fetch);
      expect(fetchMock).toHaveBeenCalledTimes(1);
      const callArgs = fetchMock.mock.calls[0];
      expect(callArgs?.[0]).toBe("http://localhost:5005/conversations/test-session/tracker");
    });
  });
});
